class Solution {
  private static final long MOD = 1_000_000_007L;

  public int kConcatenationMaxSum(int[] arr, int k) {
    long total = 0, bestPrefix = 0, bestSuffix = 0, current = 0, best = 0;
    for (int value : arr) {
      total += value;
      current = Math.max(0, current + value);
      bestPrefix = Math.max(bestPrefix, current);
    }
    current = 0;
    for (int i = arr.length - 1; i >= 0; i--) {
      current = Math.max(0, current + arr[i]);
      bestSuffix = Math.max(bestSuffix, current);
    }
    best = k == 1 ? maxSubarray(arr) : bestSuffix + bestPrefix + Math.max(0, total) * (k - 2L);
    return (int) (best % MOD);
  }

  private long maxSubarray(int[] a) {
    long cur = 0, best = 0;
    for (int x : a) {
      cur = Math.max(0, cur + x);
      best = Math.max(best, cur);
    }
    return best;
  }
}
